		<div class="elementor-element elementor-element-7d74e93 e-flex e-con-boxed e-con e-parent" data-id="7d74e93" data-element_type="container" data-settings="{&quot;jet_parallax_layout_list&quot;:[]}">
					<div class="e-con-inner">
				<div class="elementor-element elementor-element-2582861 elementor-widget elementor-widget-heading" data-id="2582861" data-element_type="widget" data-widget_type="heading.default">
